package dev.jobflow.service;
import dev.jobflow.repo.*; import java.time.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class RateLimitService {private final RateLimitBucketRepository buckets; private final int limit; public RateLimitService(RateLimitBucketRepository b,@Value("${jobflow.rate-limit.submissions-per-minute}")int l){buckets=b;limit=l;} @Transactional public void check(String subject){Instant w=Instant.now().truncatedTo(java.time.temporal.ChronoUnit.MINUTES);var bucket=buckets.lock(subject,w).orElseGet(()->buckets.saveAndFlush(new RateLimitBucket(subject,w)));int count=bucket.increment();if(count>limit)throw new RateLimitExceededException();} public static class RateLimitExceededException extends RuntimeException{public RateLimitExceededException(){super("Submission rate limit exceeded");}}}
